mapper.select:
select * from (select cc.contract_id, cc.contract_number, decode(hlm.mortgage_number,'',0,1) pledge_state, decode(hlm.mortgage_number,'','未抵押','已抵押') pledge_state_n, cc.contract_name, cc.document_type, cc.division, hlm.mortgage_id, hlm.mortgage_number, cc.manufacturer_id, (Select hbv.bp_code From hls_bp_master hbv Where hbv.bp_id = cc.manufacturer_id) manufacturer_code, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.manufacturer_id) manufacturer_id_n, cc.factory_id, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.factory_id) factory_id_n, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.tenant_id) tenant_name, ccli.contract_lease_item_id, ccli.full_name, cc.employee_id host_project_manager, (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) host_project_manager_n, hlm.actual_province_code, (select f.description from fnd_province f where f.province = hlm.actual_province_code) actual_province_code_n, hlm.actual_city_code, (select f.description from fnd_city f where f.city = hlm.actual_city_code) actual_city_code_n, hlm.vehicle_regist_number, hlm.vehicle_owner, hlm.mortgage_regist_number, hlm.mortgagee_name, hlm.mortgage_regist_date, ccli.classify_id, (select ic.attribute_value from yx_lease_item_classify ic where ic.classify_id = ccli.classify_id) classify_id_n, hlm.location, hlm.registration_authority, hlm.description from con_contract cc left join con_contract_lease_item ccli on cc.contract_id = ccli.contract_id left join hls_lease_mortgage hlm on hlm.contract_lease_item_id = ccli.contract_lease_item_id where cc.document_type in ('CONL', 'CONLB') --and cc.contract_status in ('REJECTED', 'APPROVED_RETURN', 'CONDITIONAL', 'APPROVING', 'APPROVED') and cc.division in ('Vehicle_Leasing','COMMERCIAL_VEHICLE')) v
and v.CONTRACT_NUMBER like concat(concat('%',#{contractNumber}),'%')
and v.manufacturer_id_n = #{manufacturerIdN}
and v.factory_id_n = #{factoryIdN}
and v.tenant_name like concat(concat('%',#{tenantName}),'%')
and v.full_name like concat(concat('%',#{fullName}),'%')
and v.mortgage_regist_date = to_date(#{mortgageRegistDate},'yyyy-mm-dd')
and v.pledge_state = #{pledgeState}
order by v.contract_id desc

select * from (select cc.contract_id, cc.contract_number, decode(hlm.mortgage_number,'',0,1) pledge_state, decode(hlm.mortgage_number,'','未抵押','已抵押') pledge_state_n, cc.contract_name, cc.document_type, cc.division, hlm.mortgage_id, hlm.mortgage_number, cc.manufacturer_id, (Select hbv.bp_code From hls_bp_master hbv Where hbv.bp_id = cc.manufacturer_id) manufacturer_code, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.manufacturer_id) manufacturer_id_n, cc.factory_id, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.factory_id) factory_id_n, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = cc.tenant_id) tenant_name, ccli.contract_lease_item_id, ccli.full_name, cc.employee_id host_project_manager, (select fe.name from fnd_employee fe where fe.employee_id = cc.employee_id) host_project_manager_n, hlm.actual_province_code, (select f.description from fnd_province f where f.province = hlm.actual_province_code) actual_province_code_n, hlm.actual_city_code, (select f.description from fnd_city f where f.city = hlm.actual_city_code) actual_city_code_n, hlm.vehicle_regist_number, hlm.vehicle_owner, hlm.mortgage_regist_number, hlm.mortgagee_name, hlm.mortgage_regist_date, ccli.classify_id, (select ic.attribute_value from yx_lease_item_classify ic where ic.classify_id = ccli.classify_id) classify_id_n, ccli.product_model, hlm.location, hlm.registration_authority, hlm.description from con_contract cc left join con_contract_lease_item ccli on cc.contract_id = ccli.contract_id left join hls_lease_mortgage hlm on hlm.contract_lease_item_id = ccli.contract_lease_item_id where cc.document_type in ('CONL', 'CONLB') --and cc.contract_status in ('REJECTED', 'APPROVED_RETURN', 'CONDITIONAL', 'APPROVING', 'APPROVED') and cc.division in ('Construction_machinery','ENGINEERING_MACHINERY')) v
and v.CONTRACT_NUMBER like concat(concat('%',#{contractNumber}),'%')
and v.manufacturer_id_n = #{manufacturerIdN}
and v.factory_id_n = #{factoryIdN}
and v.tenant_name like concat(concat('%',#{tenantName}),'%')
and v.full_name like concat(concat('%',#{fullName}),'%')
and v.mortgage_regist_date = to_date(#{mortgageRegistDate},'yyyy-mm-dd')
and v.pledge_state = #{pledgeState}
order by v.contract_id desc
